CREATE TABLE `users` (
  `userID` int(10) unsigned NOT NULL AUTO_INCREMENT,
  `dateCreated` datetime NOT NULL DEFAULT current_timestamp(),
  `department` varchar(150) DEFAULT NULL,
  `email` varchar(150) NOT NULL,
  `employeeId` varchar(100) DEFAULT NULL,
  `fullName` varchar(150) NOT NULL,
  `position` varchar(150) DEFAULT NULL,
  `password` varchar(255) NOT NULL,
  `role` enum('Administrator','Secretary','Technician','Employee') NOT NULL DEFAULT 'Employee',
  `canAccessAdmin` tinyint(1) NOT NULL DEFAULT 0,
  `status` enum('Active','Inactive') NOT NULL DEFAULT 'Active',
  `profilePhoto` varchar(255) DEFAULT NULL,
  PRIMARY KEY (`userID`),
  UNIQUE KEY `unique_email` (`email`),
  UNIQUE KEY `unique_employee_id` (`employeeId`),
  KEY `idx_users_department` (`department`),
  KEY `idx_users_role` (`role`),
  KEY `idx_users_status` (`status`)
) ENGINE=InnoDB AUTO_INCREMENT=5310 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;
